            typ = c.attrib.get('t')
            if typ == 'inlineStr':
                val = ''.join(t.text or '' for t in c.findall('.//a:t', NS))
            else:
                v = c.findtext('a:v', default='', namespaces=NS)
                if typ == 's' and v != '':
                    val = ss[int(v)]
                else:
                    val = v
            vals[idx] = val
        rows.append(vals)
